import 'package:flutter/material.dart';
import '../utils/app_colors.dart';
import '../models/parking_area.dart';
import '../pages/detail_page.dart';

void go(BuildContext context, Widget page) => Navigator.push(context, MaterialPageRoute(builder: (_) => page));

Widget appLogo(double size) => Image.asset('assets/images/smartpark-logo.png', width: size, height: size, fit: BoxFit.contain, errorBuilder: (_, __, ___) => Container(width: size, height: size, decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(size / 4)), child: Icon(Icons.local_parking, size: size * .65, color: green)));
Widget primaryButton(String label, VoidCallback onTap) => SizedBox(width: double.infinity, height: 50, child: ElevatedButton(onPressed: onTap, style: ElevatedButton.styleFrom(backgroundColor: green, foregroundColor: Colors.white, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)), elevation: 0), child: Text(label, style: const TextStyle(fontWeight: FontWeight.w700))));
Widget whiteButton(String label, VoidCallback onTap) => SizedBox(width: double.infinity, height: 50, child: ElevatedButton(onPressed: onTap, style: ElevatedButton.styleFrom(backgroundColor: Colors.white, foregroundColor: darkGreen, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)), elevation: 0), child: Text(label, style: const TextStyle(fontWeight: FontWeight.w700))));
Widget appPanel({required Widget child}) => Container(width: double.infinity, padding: const EdgeInsets.all(18), decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(18), boxShadow: [BoxShadow(color: Colors.black.withValues(alpha: .035), blurRadius: 14, offset: const Offset(0, 5))]), child: child);
Widget fieldLabel(String text) => Padding(padding: const EdgeInsets.only(bottom: 7), child: Text(text, style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: ink)));
Widget appField(String label, TextEditingController controller, IconData icon, {bool obscure = false, Widget? suffix}) => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [fieldLabel(label), TextField(controller: controller, obscureText: obscure, decoration: InputDecoration(prefixIcon: Icon(icon), suffixIcon: suffix, filled: true, fillColor: pale, border: OutlineInputBorder(borderRadius: BorderRadius.circular(13), borderSide: BorderSide.none), contentPadding: const EdgeInsets.symmetric(vertical: 15, horizontal: 14)))]);
Widget appDropdown(String value, List<String> values, ValueChanged<String?> onChanged) => DropdownButtonFormField<String>(initialValue: value, isExpanded: true, decoration: InputDecoration(filled: true, fillColor: pale, border: OutlineInputBorder(borderRadius: BorderRadius.circular(13), borderSide: BorderSide.none)), items: values.map((v) => DropdownMenuItem(value: v, child: Text(v, overflow: TextOverflow.ellipsis))).toList(), onChanged: onChanged);
Widget parkingTile(BuildContext context, ParkingArea p) => Container(margin: const EdgeInsets.only(bottom: 10), padding: const EdgeInsets.all(15), decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(16)), child: Row(children: [Container(width: 46, height: 46, decoration: BoxDecoration(color: const Color(0xFFE6F4EA), borderRadius: BorderRadius.circular(12)), child: const Icon(Icons.local_parking, color: darkGreen)), const SizedBox(width: 12), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(p.name, style: const TextStyle(fontWeight: FontWeight.w700)), Text('${p.available} slot kosong · ${p.location}', style: const TextStyle(color: muted, fontSize: 11))])), TextButton(onPressed: () => go(context, DetailPage(parking: p)), child: const Text('Lihat Detail'))]));
